#!/usr/bin/env python3
"""Build an offline frame atlas; --embed creates one portable HTML file."""
import argparse, base64, html, json
from pathlib import Path
p=argparse.ArgumentParser()
p.add_argument('assets',type=Path)
p.add_argument('output',type=Path)
p.add_argument('--embed',action='store_true')
a=p.parse_args()
root=a.assets.resolve()
manifest=json.loads((root/'frames/manifest.json').read_text(encoding='utf-8'))
refs=json.loads((root/'external-sources.json').read_text(encoding='utf-8'))
def asset(name):
    if a.embed:
        mime='video/mp4' if name.endswith('.mp4') else 'image/jpeg'
        return 'data:'+mime+';base64,'+base64.b64encode((root/name).read_bytes()).decode()
    import os
    return Path(os.path.relpath(root/name,a.output.parent.resolve())).as_posix()
frames=[dict(f,src=asset('frames/'+f['file'])) for f in manifest['frames']]
cards=[]
for r in refs:
    if not r.get('local_available',False): continue
    cards.append('<article><img loading="lazy" src="'+asset(r['file'])+'" alt="'+html.escape(r['title'],quote=True)+'"><h3>'+html.escape(r['title'])+'</h3><p>'+html.escape(r['niche'])+'</p><p>'+html.escape(str(r['time']))+'</p><a href="'+html.escape(r['page'],quote=True)+'" target="_blank" rel="noreferrer">Fonte e autoria ↗</a></article>')
page='''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Motion Production · Modelo BeSafe</title>
<style>*{box-sizing:border-box}body{margin:0;background:#0b2023;color:#f0f4e9;font:16px/1.5 Arial,sans-serif}main{max-width:1280px;padding:48px 28px;margin:auto}a{color:#c4f57e}h1{font-size:clamp(36px,6vw,70px);line-height:1.05;letter-spacing:-.04em;margin:10px 0 18px}h2{font-size:28px;margin-top:48px}p{color:#b8cbc4;max-width:900px}.eyebrow{color:#c4f57e;letter-spacing:.16em;font-size:12px;font-weight:bold}#frame,video{display:block;width:100%;aspect-ratio:16/9;object-fit:contain;background:#061314;border-radius:16px}.controls{display:flex;gap:12px;flex-wrap:wrap;align-items:center;padding:16px 0}button,input,select{font:inherit}button,select{padding:10px 15px;border:1px solid #446158;border-radius:9px;background:#16352f;color:#edf4e5;cursor:pointer}button:hover{background:#2b5345}input[type=range]{flex:1;min-width:150px;accent-color:#c4f57e}input[type=number]{width:90px;background:#16352f;color:white;border:1px solid #557066;border-radius:8px;padding:8px}.info{display:grid;grid-template-columns:1fr 2fr;gap:18px;padding:22px;background:#16302e;border-radius:16px;margin:6px 0 28px}.info h3,.info p{margin:0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:22px}.grid img{width:100%;aspect-ratio:16/10;object-fit:contain;background:#07191c;border-radius:12px}.grid article{padding:16px;background:#16302e;border-radius:16px}.grid h3{font-size:18px}.grid p{font-size:14px}details{padding:20px;background:#16302e;border-radius:16px;margin:20px 0}summary{cursor:pointer;font-weight:bold}.note{border-left:3px solid #c4f57e;padding:4px 18px}footer{padding:50px 0 0;color:#a9bfb5;font-size:13px}button:focus-visible,input:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #c4f57e;outline-offset:3px}@media(max-width:600px){main{padding:28px 14px}.info{grid-template-columns:1fr}h2{font-size:24px}}</style>
<main><div class="eyebrow">MOTION PRODUCTION / ESTUDO BESAFE</div><h1>Continuidade que<br>ajuda a entender.</h1><p>Acervo de consulta do modelo de 20 segundos. Navegue por cada um dos 600 quadros, observe a trajetória dos elementos e consulte referências de outros nichos.</p>
<h2>Modelo • quadro a quadro</h2><img id="frame" alt="Quadro do motion educativo de investimentos">
<div class="controls"><button id="prev" aria-label="Quadro anterior">←</button><button id="next" aria-label="Próximo quadro">→</button><label for="slider">Tempo</label><input id="slider" type="range" min="0" max="599" value="0"><label for="number">Quadro</label><input id="number" type="number" min="0" max="599" value="0"><output id="time" aria-live="polite"></output></div>
<div class="controls"><label for="beats">Ir para:</label><select id="beats"><option value="0">Abertura</option><option value="80">Concentração</option><option value="200">Pergunta</option><option value="222">Clique</option><option value="246">Redistribuição</option><option value="363">Consequência</option><option value="437">Conclusão</option><option value="599">Último quadro</option></select></div>
<div class="info"><h3 id="beat"></h3><p id="mechanism"></p></div>
<details><summary>Assistir ao modelo completo • 20 s, sem áudio</summary><video controls preload="none" src="__VIDEO__"></video></details>
<p class="note">Os números e controles pertencem apenas ao catálogo. O vídeo não contém etiquetas de slides. Quadros próprios em JPEG, 1440 × 810, sem interpolação; índices 0–599 e timestamps preservados.</p>
<h2>Referências visuais</h2><p>9 amostras locais de cibersegurança, SaaS e bem-estar. São stills publicados ou frames selecionados, não extrações integrais dos filmes. Use os mecanismos como referência e produza imagens próprias.</p><div class="grid">__CARDS__</div>
<h2>Vídeos enviados por você</h2><p>As quatro referências abaixo foram analisadas automaticamente. O acesso aos arquivos exigiu autenticação; por isso, não há prints internos delas neste catálogo. Tempos sugeridos são pistas de consulta, sujeitos a conferência.</p>
<ul><li><a href="https://www.youtube.com/watch?v=4xRRR2mjtts">V01 — gancho e interação</a> · 00:00–00:06 / 00:14–00:18</li><li><a href="https://www.youtube.com/watch?v=2moKxAZjwCE">V02 — UI, brief e revisão</a> · 00:47–00:52 / 03:41–05:05</li><li><a href="https://www.youtube.com/watch?v=4wk7nTZler4">V03 — regras, beats e resultado</a> · 05:50–07:57 / 18:16–21:02</li><li><a href="https://www.youtube.com/watch?v=8bBo-BEPb-M">V04 — geometria, luz e hierarquia</a> · 00:00–00:06 / 00:12–00:20</li></ul>
<details><summary>Higgsfield • limite da verificação</summary><p>Em 17/11/2026, Vibe Motion redirecionou para Supercomputer. A página AI Motion Design anuncia fluxo code-to-video, cores, posição, easing, fontes e exportação até 4K. Esses controles foram documentados, sem teste de geração. Três imagens de AI Motion Designer vistas na pesquisa anterior não foram incluídas: a URL de mídia retornou HTTP 403. AI Motion Designer para Adobe e motion nativo no navegador são rotas distintas.</p><a href="https://higgsfield.ai/ai-motion-design">Página oficial de AI Motion Design ↗</a></details>
<footer>BeSafe · acervo de estudo · 17/11/2026<br>Prioridades: texto legível, uma ação focal, entidades persistentes, cursor alinhado, pausas de leitura e dados fictícios.</footer></main>
<script>const frames=__FRAMES__;let index=0;const el=id=>document.getElementById(id);const beats=[{end:2.65,title:'Gancho / contexto',text:'Título grande e carteira como âncora. O cursor se aproxima do dado que será explicado.'},{end:6.65,title:'Concentração / zoom semântico',text:'A mesma janela se amplia. Spotlight e sublinhado isolam 100%, mantendo o contexto.'},{end:8.2,title:'Pergunta / ação',text:'O cursor se desloca ao botão; pressão e ripple dão uma causa visual à mudança.'},{end:12.1,title:'Redistribuição / persistência',text:'As seis moedas preservam identidade e contagem. Arcos e chegadas escalonadas tornam o deslocamento rastreável.'},{end:14.55,title:'Consequência / pausa',text:'A composição estabiliza para a leitura de Menos concentração. O foco deixa de competir com o movimento.'},{end:21,title:'Conclusão / limite',text:'A carteira permanece na tela. O risco continua recebe hierarquia; a ressalva fica visível durante a pausa final.'}];function show(n){index=Math.max(0,Math.min(frames.length-1,Math.round(Number(n)||0)));const f=frames[index],b=beats.find(x=>f.time<x.end);el('frame').src=f.src;el('frame').alt='Quadro '+index+' — '+b.title;el('slider').value=index;el('number').value=index;el('time').textContent=f.time.toFixed(3)+' s';el('beat').textContent=b.title;el('mechanism').textContent=b.text;}el('prev').onclick=()=>show(index-1);el('next').onclick=()=>show(index+1);el('slider').oninput=e=>show(e.target.value);el('number').onchange=e=>show(e.target.value);el('beats').onchange=e=>show(e.target.value);document.addEventListener('keydown',e=>{if(['INPUT','SELECT','VIDEO'].includes(e.target.tagName))return;if(e.key==='ArrowRight'){e.preventDefault();show(index+1)}if(e.key==='ArrowLeft'){e.preventDefault();show(index-1)}});show(0);</script></html>'''
page=page.replace('__VIDEO__',asset('model.mp4')).replace('__CARDS__',''.join(cards)).replace('__FRAMES__',json.dumps(frames,ensure_ascii=False))
a.output.parent.mkdir(parents=True,exist_ok=True)
a.output.write_text(page,encoding='utf-8')
print(json.dumps({'output':str(a.output),'frames':len(frames),'external_images':len(cards),'bytes':a.output.stat().st_size}))
